display_oracle() = isempty(get(ENV,"JF2_DISPLAY_ORACLE","")) ? JSON.parse(DISPLAY_CAPTURE) : JSON.parsefile(ENV["JF2_DISPLAY_ORACLE"])
function display_item_json(item)
    Dict("sourceId"=>item.source_entry_id,"timestamp"=>item.timestamp,"payload"=>item.payload)
end
@testset "Original Pi raw display pipeline differential" begin
    oracle=display_oracle()
    @test oracle["pin"]=="2c8d1feb147f6b3d97e855da803bfe7b19f3c403"
    for fixture in oracle["cases"]
        @testset "$(fixture["name"])" begin
            original=deepcopy(fixture["entries"])
            projection=TD.timeline_display_projection(fixture["entries"];mode=Symbol(get(fixture,"mode","pi")))
            @test projection.entries==fixture["expected"]["entries"]
            @test display_item_json.(projection.items)==fixture["expected"]["items"]
            view=TD.timeline_display_records(projection;show_usage=get(fixture,"showUsage",false),custom_entry_visible=Returns(get(fixture,"customRenderer",false)),retry_attempt=get(fixture,"retryAttempt",0))
            observations=[Dict("sourceId"=>record.item.source_entry_id,"role"=>record.item.payload["role"],"visible"=>record.visible) for record in view.records if record.item.kind==:message && record.item.payload["role"]!="toolResult"]
            expected=[Dict(key=>item[key] for key in ("sourceId","role","visible")) for item in fixture["expected"]["observations"]]
            @test observations==expected
            tools=[Dict("id"=>tool.call["id"],"name"=>tool.call["name"],"args"=>tool.call["arguments"],"result"=>tool.result) for tool in view.tools]
            @test tools==fixture["expected"]["tools"]
            nonmessages=[Dict("sourceId"=>record.item.source_entry_id,"kind"=>String(record.item.kind),"visible"=>record.visible) for record in view.records if record.item.kind!=:message]
            @test nonmessages==fixture["expected"]["itemObservations"]
            @test fixture["entries"]==original
        end
    end
end

@testset "Display preserves originals while context alone is edited" begin
    fixture=only(filter(x->x["name"]=="compaction-edits",display_oracle()["cases"]))
    projection=TD.timeline_display_projection(fixture["entries"])
    @test only(filter(item->item.source_entry_id=="u2",projection.items)).payload["content"][1]["text"]=="U2"
    @test only(filter(entry->entry.source_entry["id"]=="u2",TD.timeline_projection(fixture["entries"]).entries)).messages[1]["content"]=="Edited U2"
    full=TD.timeline_display_projection(fixture["entries"];mode=:archive)
    @test any(item->item.source_entry_id=="u1",full.items)
    @test !any(item->item.source_entry_id=="u1",projection.items)
    @test_throws ErrorException TD.timeline_display_projection(fixture["entries"];mode=:unknown)
    @test_throws ErrorException TD.timeline_display_projection(fixture["entries"];leaf="missing")
    @test isempty(TD.timeline_display_projection(fixture["entries"];leaf=nothing).items)
    original=deepcopy(fixture["entries"])
    projection.items[1].payload["content"]="mutated snapshot"
    @test fixture["entries"]==original
    @test projection.entries[1]["systemMessage"]["content"]=="System checkpoint"
end

@testset "Visible shell output, custom entries, costs and inline tools" begin
    fixture=only(filter(x->x["name"]=="rich",display_oracle()["cases"]))
    projection=TD.timeline_display_projection(fixture["entries"])
    view=TD.timeline_display_records(projection)
    byid(id)=only(filter(record->record.item.source_entry_id==id,view.records))
    @test byid("bashhidden").visible
    @test byid("bashhidden").item.payload["excludeFromContext"]
    @test !byid("hidden").visible
    @test byid("visible").visible
    @test !byid("state").visible
    @test byid("result").related_tool_id=="call1"
    @test view.tools[1].result_entry_id=="result"
    @test view.tools[1].call["arguments"]==Dict("path"=>"fixture")
    @test view.tools[1].result["toolCallId"]=="call1"
    exposed=TD.timeline_display_records(projection;custom_entry_visible=entry->entry["customType"]=="opaque.state")
    @test only(filter(record->record.item.source_entry_id=="state",exposed.records)).visible
    original=deepcopy(projection.items[1].payload)
    view.records[1].item.payload["content"]="changed"
    @test projection.items[1].payload==original
    costs=only(filter(x->x["name"]=="summary-usage",display_oracle()["cases"]))
    hidden=TD.timeline_display_records(TD.timeline_display_projection(costs["entries"]))
    shown=TD.timeline_display_records(TD.timeline_display_projection(costs["entries"]);show_usage=true)
    @test !last(hidden.records).visible
    @test last(shown.records).visible
    @test last(shown.records).item.payload["usage"]["cost"]["total"]==0.01
end

@testset "Display-native adapters cannot silently lose unsupported content or become context" begin
    timeline=TD.SessionTimeline("/tmp")
    TD.timeline_append_message!(timeline,TD.timeline_archive_message(Message(:user,"question")))
    TD.timeline_append_message!(timeline,TD.timeline_archive_message(Message(:assistant,"x=42",:code)))
    TD.timeline_append_message!(timeline,TD.timeline_archive_message(Message(:code_result,"42";metadata=TD.ExecutionResult(true,"42",42))))
    messages=TD.timeline_display_messages(timeline)
    @test [message.role for message in messages]==[:user,:assistant,:code_result]
    @test [message.kind for message in messages]==[:text,:code,:text]
    @test [message.content for message in messages]==["question","x=42","42"]
    @test_throws ErrorException TD.wire_content(messages[1])
    signed=Dict("role"=>"assistant","content"=>[Dict("type"=>"text","text"=>"signed text","textSignature"=>"opaque")])
    TD.timeline_append_message!(timeline,signed)
    displayed=last(TD.timeline_display_messages(timeline))
    @test displayed.content=="signed text"
    @test displayed.metadata.record.item.payload["content"][1]["textSignature"]=="opaque"
    @test_throws ErrorException TD.timeline_runtime_messages(timeline)
    @test_throws ErrorException TD.timeline_display_messages(timeline;mapper=record->nothing)
    rich=only(filter(x->x["name"]=="rich",display_oracle()["cases"]))
    @test_throws ErrorException TD.timeline_display_messages(TD.timeline_display_projection(rich["entries"]))
    mapped=TD.timeline_display_messages(TD.timeline_display_projection(rich["entries"]);mapper=record->Message(:user,JSON.json(record.item.payload)))
    @test any(message->occursin("thinkingSignature",message.content),mapped)
    @test any(message->occursin("excludeFromContext",message.content),mapped)
    @test !any(message->occursin("Hidden but in context",message.content),mapped)
end

@testset "Aborted and error tool calls have real terminal results, not pending placeholders" begin
    timeline=TD.SessionTimeline("/tmp")
    call=Dict("type"=>"toolCall","id"=>"x","name"=>"read","arguments"=>Dict("path"=>"fixture"))
    TD.timeline_append_message!(timeline,Dict("role"=>"assistant","content"=>[call],"stopReason"=>"aborted");id="call")
    TD.timeline_append_message!(timeline,Dict("role"=>"toolResult","toolCallId"=>"x","content"=>"late result");id="result")
    view=TD.timeline_display_records(timeline;retry_attempt=2)
    @test only(view.tools).result["content"][1]["text"]=="Aborted after 2 retry attempts"
    @test only(view.tools).result["isError"]
    @test !last(view.records).visible
    @test only(view.tools).result_entry_id===nothing
    other=TD.SessionTimeline("/tmp")
    TD.timeline_append_message!(other,Dict("role"=>"assistant","content"=>[call],"stopReason"=>"error","errorMessage"=>"Actual failure"))
    @test only(TD.timeline_display_records(other).tools).result["content"][1]["text"]=="Actual failure"
end

@testset "Unknown message presentations are explicit, never silently filtered" begin
    timeline=TD.SessionTimeline("/tmp")
    TD.timeline_append_message!(timeline,Dict("role"=>"future-extension","content"=>"opaque preserved"))
    record=only(TD.timeline_display_records(timeline).records)
    @test record.visible
    @test record.presentation==:unsupported
    @test record.item.payload["content"]=="opaque preserved"
    @test_throws ErrorException TD.timeline_display_messages(timeline)
end
